function initials(name){ return name.split(" ").map(p=>p[0]).slice(0,2).join("").toUpperCase(); }
function showToast(message){ const toast=$("#toast"); toast.textContent=message; toast.classList.add("show"); setTimeout(()=>toast.classList.remove("show"),2600); }
function statCard(label,value,meta,icon,warning=false){ return `<div class="stat-card"><span class="stat-icon">${icon}</span><div class="stat-label">${label}</div><div class="stat-value">${value}</div><div class="stat-meta ${warning?"warning":""}">${meta}</div></div>`; }
function layout(title,content,subtitle="Manage and organize your college information in one place."){ return `<div class="page"><div class="page-heading"><div><h1>${title}</h1><p>${subtitle}</p></div></div>${content}</div>`; }
