function render(){ const fallback=currentRole==="Student"?"student-home":currentRole==="Teacher"?"teacher-home":"overview"; const viewName=currentView==="overview"?fallback:currentView; $("#viewContainer").innerHTML=views[viewName](); $("#pageTitle").textContent=viewName.replace("my-","My ").replace("teacher-","Teacher ").replace("-"," ").replace(/\b\w/g,c=>c.toUpperCase()); document.querySelectorAll(".nav-item").forEach(n=>n.classList.toggle("active",n.dataset.view===viewName)); bindViewEvents(); }
let cameraStream=null,cameraTimer=null,previousEyeFrame=null,blinkCooldown=0,cameraAttendanceMarked=false;
function closeCameraAttendance(){ if(cameraTimer){clearInterval(cameraTimer);cameraTimer=null;} if(cameraStream){cameraStream.getTracks().forEach(track=>track.stop());cameraStream=null;} previousEyeFrame=null;$("#modalRoot").innerHTML=""; }
function markCameraStudentPresent(){ if(cameraAttendanceMarked)return false;const select=document.querySelector(".attendance-select");if(select){select.value="Present";select.classList.add("camera-marked");setTimeout(()=>select.classList.remove("camera-marked"),1400);cameraAttendanceMarked=true;return true;}if(currentRole==="Student"){const student=currentStudent();const today=new Date().toLocaleDateString("en-GB",{day:"2-digit",month:"short"});const records=attendanceRecords[student.id]||[];if(!records.some(record=>record[0]===today&&record[1]==="Present"))records.unshift([today,"Present","Camera blink"]);attendanceRecords[student.id]=records.slice(0,20);student.attendance=Math.min(100,student.attendance+1);localStorage.setItem("campusflow-attendance",JSON.stringify(attendanceRecords));save();cameraAttendanceMarked=true;return true;}return false; }
function inspectBlink(video,canvas,status){ if(video.readyState<2||blinkCooldown>0)return;const ctx=canvas.getContext("2d",{willReadFrequently:true});ctx.drawImage(video,0,0,canvas.width,canvas.height);const frame=ctx.getImageData(70,55,180,65).data;let difference=0;if(previousEyeFrame){for(let i=0;i<frame.length;i+=4)difference+=Math.abs(frame[i]-previousEyeFrame[i])+Math.abs(frame[i+1]-previousEyeFrame[i+1])+Math.abs(frame[i+2]-previousEyeFrame[i+2]);difference/=frame.length/4;}previousEyeFrame=frame;if(difference>32){blinkCooldown=16;status.textContent="Blink detected — student marked Present";status.className="camera-status detected";if(markCameraStudentPresent())showToast("Blink verified: student marked Present");}else if(status.classList.contains("detected"))status.textContent="Camera ready — blink again to mark present";if(blinkCooldown>0)blinkCooldown--; }
async function openCameraAttendance(){ cameraAttendanceMarked=false;const isStudent=currentRole==="Student";$("#modalRoot").innerHTML=`<div class="modal-backdrop" id="cameraBackdrop"><div class="modal-card camera-modal"><div class="modal-header"><div><h2>Camera blink attendance</h2><p>${isStudent?"Look at the camera and blink once to mark your attendance.":"Look at the camera and blink once to mark the selected student Present."}</p></div><button class="modal-close" id="closeCamera">×</button></div><div class="camera-preview"><video id="attendanceCamera" autoplay muted playsinline></video><canvas id="attendanceCanvas" width="320" height="240"></canvas><span class="camera-live-pill">LIVE CAMERA</span></div><p id="cameraStatus" class="camera-status">Requesting camera access…</p><div class="camera-actions"><button class="outline-button" id="retryCamera">Start camera</button><button class="primary-button" id="finishCamera">Done</button></div><small class="camera-note">Camera processing stays in this browser. No video is uploaded.</small></div></div>`;$("#closeCamera").onclick=closeCameraAttendance;$("#finishCamera").onclick=closeCameraAttendance;$("#cameraBackdrop").onclick=e=>{if(e.target.id==="cameraBackdrop")closeCameraAttendance();};const start=async()=>{const video=$("#attendanceCamera"),canvas=$("#attendanceCanvas"),status=$("#cameraStatus");if(!navigator.mediaDevices||!navigator.mediaDevices.getUserMedia){status.textContent="Camera is unavailable on this page. Use HTTPS or localhost.";status.className="camera-status error";return;}try{if(cameraStream)cameraStream.getTracks().forEach(track=>track.stop());cameraStream=await navigator.mediaDevices.getUserMedia({video:{facingMode:"user",width:{ideal:640},height:{ideal:480}},audio:false});video.srcObject=cameraStream;await video.play();previousEyeFrame=null;status.textContent="Camera ready — blink to mark present";status.className="camera-status";if(cameraTimer)clearInterval(cameraTimer);cameraTimer=setInterval(()=>inspectBlink(video,canvas,status),120);}catch(error){status.textContent=error.name==="NotAllowedError"?"Camera permission was denied. Allow access and try again.":"Unable to start camera. Check that a camera is connected.";status.className="camera-status error";}};$("#retryCamera").onclick=start;await start();}
function bindViewEvents(){
  document.querySelectorAll("[data-view-link]").forEach(el=>el.onclick=()=>{currentView=el.dataset.viewLink;render()});
  const cameraButton=$("#openCameraAttendance");if(cameraButton)cameraButton.onclick=openCameraAttendance;
  const search=$("#studentSearch"); if(search) search.oninput=()=>$("#studentRows").innerHTML=studentRows(students.filter(s=>(s.name+s.id+s.course).toLowerCase().includes(search.value.toLowerCase())));
  document.querySelectorAll(".clickable-row").forEach(row=>row.onclick=()=>openStudentHistory(row.dataset.studentId));
  document.querySelectorAll(".toggle").forEach(t=>t.onclick=()=>t.classList.toggle("on"));
  const actions={newNotice:"Notice composer is ready",addCourse:"Course form is ready",downloadResults:"Results report downloaded",exportReport:"Analytics report exported",recordPayment:"Payment form is ready",issueBook:"Book issue form is ready",addFaculty:"Faculty form is ready",payFees:"Secure payment window is ready",addEvent:"Calendar event form is ready",composeMessage:"New message composer is ready",uploadAssignment:"Upload window is ready",saveTeacherAttendance:"Live attendance published",addTeacherClass:"Class form is ready",sendFeeReminder:"Fee reminders queued",processPayroll:"Payroll batch is ready",newAdmission:"Admission enquiry form is ready",generateCertificate:"Certificate generator is ready",verifyCertificate:"Certificate verification ready",importData:"Select an Excel or CSV file",exportData:"ERP data export prepared",backupData:"Backup snapshot created",restoreData:"Demo backup restored",qrAttendance:"QR attendance code generated",openChatbot:"AI campus assistant ready",newLeave:"Leave application form ready",allocateRoom:"Room allocation form ready",trackBus:"Live bus tracking ready",newScholarship:"Scholarship application ready",inviteAlumni:"Alumni invitation ready",newClub:"Club registration ready",editMenu:"Canteen menu editor ready",newVisitor:"Visitor registration ready",runPayroll:"HR payroll processing ready",newTicket:"Helpdesk ticket form ready",addAsset:"Asset registration ready",newResearch:"Research submission ready",uploadDocument:"Document upload ready",downloadAdmit:"Admit card prepared"};
  Object.keys(actions).forEach(id=>{const el=$("#"+id);if(el)el.onclick=()=>showToast(actions[id])});
  document.querySelectorAll(".reminder-button").forEach(button=>button.onclick=()=>showToast("Reminder sent to the selected student"));
  document.querySelectorAll(".certificate-card").forEach(button=>button.onclick=()=>showToast("Certificate template selected"));
  document.querySelectorAll(".download-certificate").forEach(button=>button.onclick=()=>showToast("Certificate download prepared"));
  document.querySelectorAll(".social-highlight").forEach(button=>button.onclick=()=>showToast(button.querySelector("b").textContent+" highlight selected"));
  const language=$("#languageToggle");if(language)language.onclick=()=>{document.documentElement.lang=document.documentElement.lang==="hi"?"en":"hi";showToast(document.documentElement.lang==="hi"?"Hindi preview enabled":"English preview enabled");};
  document.querySelectorAll(".review-assignment").forEach(button=>button.onclick=()=>showToast("Assignment review opened"));
  const saveAttendanceButton=$("#saveAttendance"); if(saveAttendanceButton) saveAttendanceButton.onclick=()=>{ document.querySelectorAll(".attendance-select").forEach(select=>{const id=select.dataset.studentId;const record=attendanceRecords[id] || [];record.unshift(["18 Jun",""+select.value,"Live update"]);attendanceRecords[id]=record.slice(0,20);const student=students.find(s=>s.id===id);if(student && select.value==="Present")student.attendance=Math.min(100,student.attendance+1);if(student && select.value==="Absent")student.attendance=Math.max(0,student.attendance-1);});localStorage.setItem("campusflow-attendance",JSON.stringify(attendanceRecords));save();liveActivity.unshift("Attendance register published · just now");render();showToast("Live attendance changes published");};
  const add=$("#addStudent"); if(add) add.onclick=()=>{ const name=prompt("Student name"); if(!name)return; const newStudent={id:`STU-${1024+students.length}`,name,email:`${name.toLowerCase().replaceAll(" ",".")}@campus.edu`,course:"B.Tech Computer Science",year:"1st Year",attendance:100,status:"Active",initials:initials(name)}; students.push(newStudent);save();render();showToast("Student record added"); };
}
function openStudentHistory(id){ const s=students.find(student=>student.id===id);if(!s)return;const records=attendanceRecords[id]||[];$("#modalRoot").innerHTML=`<div class="modal-backdrop" id="historyBackdrop"><div class="modal-card"><div class="modal-header"><div><h2>Student profile & history</h2><p>Complete academic record and live attendance timeline</p></div><button class="modal-close" id="closeHistory">×</button></div><div class="profile-banner"><div class="avatar">${s.initials}</div><div><b>${s.name}</b><small>${s.id} · ${s.course} · ${s.year}</small></div><span class="live-pill" style="margin-left:auto">LIVE RECORD</span></div><div class="stats-grid">${statCard("Attendance",`${s.attendance}%`,"Current semester","✓")} ${statCard("Current status",s.status,"Enrolled student","◉")} ${statCard("Classes attended","46","This semester","↗")} ${statCard("CGPA","8.42","Out of 10.00","✦")}</div><h3 class="history-title">Attendance history</h3><table class="history-table"><thead><tr><th>Date</th><th>Subject</th><th>Status</th><th>Source</th></tr></thead><tbody>${records.map(r=>`<tr><td>${r[0]}</td><td>${r[2]}</td><td><span class="status ${r[1]!=="Present"?"absent":""}">${r[1]}</span></td><td>Faculty register</td></tr>`).join("")}</tbody></table><h3 class="history-title">Academic history</h3><table class="history-table"><tbody><tr><td>2024-25</td><td>Semester III</td><td>CGPA 8.42</td><td>Promoted</td></tr><tr><td>2023-24</td><td>Semester II</td><td>CGPA 8.18</td><td>Completed</td></tr></tbody></table></div></div>`;$("#closeHistory").onclick=()=>$("#modalRoot").innerHTML="";$("#historyBackdrop").onclick=e=>{if(e.target.id==="historyBackdrop")$("#modalRoot").innerHTML=""}; }
document.querySelectorAll('input[name="role"]').forEach(r=>r.onchange=()=>{document.querySelectorAll(".role-option").forEach(o=>o.classList.toggle("active",o.querySelector("input").checked));const protectedAdmin=document.querySelector('input[name="role"]:checked').value==="Admin";$("#passwordLabel").style.display=protectedAdmin?"block":"none";$("#passwordField").style.display=protectedAdmin?"block":"none";});
window.setTimeout(()=>{const loading=$("#loadingScreen");if(loading){loading.classList.add("loaded");window.setTimeout(()=>loading.remove(),650);}},1700);
$("#togglePassword").onclick=()=>{const p=$("#password");p.type=p.type==="password"?"text":"password";$("#togglePassword").textContent=p.type==="password"?"Show":"Hide"};
$("#loginForm").onsubmit=e=>{e.preventDefault();currentRole=document.querySelector('input[name="role"]:checked').value;const password=$("#password").value;const valid=currentRole!=="Admin"||password==="admin123";if(!valid){showToast("Invalid admin password");return;}currentStudentId="STU-1024";currentView="overview";document.body.classList.toggle("student-mode",currentRole==="Student");document.body.classList.toggle("teacher-mode",currentRole==="Teacher");$("#loginScreen").classList.add("hidden");$("#appShell").classList.remove("hidden");$("#sidebarUser").textContent=currentRole==="Admin"?"Admin User":currentRole==="Teacher"?"Teacher User":"Aarav Sharma";$("#sidebarRole").textContent=currentRole==="Admin"?"Administrator":currentRole;$("#userAvatar").textContent=currentRole[0];render();showToast(`Welcome to your ${currentRole.toLowerCase()} workspace`);};
document.querySelectorAll(".nav-item").forEach(n=>n.onclick=()=>{currentView=n.dataset.view;render()});
const closeMobileNav=()=>{document.body.classList.remove("mobile-nav-open");const menu=$("#mobileMenuButton");if(menu)menu.setAttribute("aria-expanded","false");};
const mobileMenu=$("#mobileMenuButton");if(mobileMenu)mobileMenu.onclick=()=>{const open=document.body.classList.toggle("mobile-nav-open");mobileMenu.setAttribute("aria-expanded",open?"true":"false");};
const mobileBackdrop=$("#mobileNavBackdrop");if(mobileBackdrop)mobileBackdrop.onclick=closeMobileNav;
document.querySelectorAll(".sidebar .nav-item").forEach(n=>n.addEventListener("click",()=>{if(window.innerWidth<=768)closeMobileNav();}));
$("#logoutButton").onclick=()=>{$("#appShell").classList.add("hidden");$("#loginScreen").classList.remove("hidden");document.body.classList.remove("student-mode","teacher-mode");currentRole="Admin";currentView="overview";showToast("You have been logged out");};
setInterval(()=>{const clock=$("#liveClock");if(clock)clock.textContent=new Date().toLocaleTimeString([], {hour12:false});},1000);
setInterval(()=>{if(!$("#appShell").classList.contains("hidden"))showToast(currentRole==="Admin"?"Live sync: attendance feed updated":"Live sync: new campus update available");},18000);
